"""Topic-policy clause libraries: Acceptable Use, Identity and Access Management, Classification, Incidents."""
from .common import C, S, V, topic_frame

has = lambda code, *v: (lambda p: p.has(code, *v))  # noqa: E731

# ------------------------------------------------------------------ Acceptable Use
AUP = topic_frame(
    purpose=[C("P01", "This policy sets the rules that every user of {org}’s information and technology must follow, so that these resources are used lawfully, safely and for the purposes of {org}.",
               "La présente politique fixe les règles que doit suivre tout utilisateur de l’information et des technologies de {org}, afin que ces ressources soient utilisées légalement, de façon sécuritaire et aux fins de {org}.", mod="info")],
    scope_extra=[],
    roles=[
        C("R01", "Users read, acknowledge and follow this policy and report suspected incidents.", "Les utilisateurs lisent, reconnaissent et respectent la présente politique et signalent les incidents soupçonnés."),
        C("R02", "Managers make sure their staff know this policy and address misuse.", "Les gestionnaires s’assurent que leur personnel connaît la présente politique et interviennent en cas de mauvais usage."),
        C("R03", "Human resources obtains acknowledgements at onboarding and keeps a record of them.", "Les ressources humaines obtiennent les attestations à l’accueil et les consignent."),
        C("R04", "{sec} maintains this policy and the technical measures that support it.", "{sec} tient à jour la présente politique et les mesures techniques qui la soutiennent."),
    ],
    requirements=[
        S("SEC-REQ-GENERAL", "General use", "Utilisation générale", [
            C("G01", "Users must use {org}’s information and technology for authorized business purposes and only to the extent of the access granted to them.",
              "Les utilisateurs doivent utiliser l’information et les technologies de {org} à des fins professionnelles autorisées et dans la seule mesure des accès qui leur sont accordés.", refs=["ISO 27002:2022 5.10"]),
            C("G02", by="DEC-AUP-PERSONAL", src="decision", variants={
                "limited": V("Limited personal use is permitted if it is occasional, does not interfere with work, does not create costs or risks for {org} and complies with this policy. Users have no expectation that personal content on {org} systems is private from authorized security activities.",
                             "Une utilisation personnelle limitée est permise si elle est occasionnelle, ne nuit pas au travail, n’entraîne ni coût ni risque pour {org} et respecte la présente politique. Les utilisateurs ne doivent pas s’attendre à ce que leur contenu personnel sur les systèmes de {org} échappe aux activités de sécurité autorisées."),
                "no": V("Personal use of {org}’s technology is not permitted.", "L’utilisation personnelle des technologies de {org} n’est pas permise."),
                "_none": V("[DECISION: State whether limited personal use of work technology is permitted.]", "[DÉCISION : Préciser si une utilisation personnelle limitée des technologies de travail est permise.]")}),
            C("G03", "Users must protect information according to its classification, including when printing, sharing, storing or discussing it.",
              "Les utilisateurs doivent protéger l’information selon sa classification, y compris lorsqu’ils l’impriment, la partagent, la conservent ou en discutent.", refs=["ISO 27002:2022 5.13"]),
            C("G04", "Users must lock their screen when they leave their device and must not leave confidential information unattended on desks, printers or screens.",
              "Les utilisateurs doivent verrouiller leur écran lorsqu’ils s’éloignent de leur appareil et ne doivent pas laisser d’information confidentielle sans surveillance sur un bureau, une imprimante ou un écran.", refs=["ISO 27002:2022 7.7"]),
        ]),
        S("SEC-REQ-ACCOUNTS", "Accounts and credentials", "Comptes et authentifiants", [
            C("A01", "Users must not share their accounts, passwords, tokens or other authenticators, and must not use another person’s account.",
              "Les utilisateurs ne doivent pas partager leurs comptes, mots de passe, jetons ou autres authentifiants, ni utiliser le compte d’une autre personne.", mod="must not", refs=["ISO 27002:2022 5.17"]),
            C("A02", "Users must use unique passwords for {org} accounts, store them only in a password manager approved by {sec}, and change them immediately if they may have been disclosed.",
              "Les utilisateurs doivent utiliser des mots de passe uniques pour les comptes de {org}, les conserver uniquement dans un gestionnaire de mots de passe approuvé par {sec} et les changer immédiatement s’ils ont pu être divulgués.", refs=["ISO 27002:2022 5.17"]),
        ]),
        S("SEC-REQ-PROHIBITED", "Prohibited activities", "Activités interdites", [
            C("X01", "Users must not: (a) attempt to bypass or disable security controls; (b) install unapproved software or connect unapproved devices to {org} systems; (c) access, copy or disclose information without authorization; (d) scan, probe or test systems without written authorization from {sec}; (e) use {org} resources for illegal, harassing, discriminatory or offensive activities; (f) infringe copyright or licence terms; (g) send {org} information to personal email or storage accounts.",
              "Les utilisateurs ne doivent pas : a) tenter de contourner ou de désactiver des mesures de sécurité; b) installer des logiciels non approuvés ou brancher des appareils non approuvés aux systèmes de {org}; c) accéder à de l’information, la copier ou la communiquer sans autorisation; d) balayer, sonder ou tester des systèmes sans l’autorisation écrite de {sec}; e) utiliser les ressources de {org} à des fins illégales, harcelantes, discriminatoires ou offensantes; f) enfreindre des droits d’auteur ou des conditions de licence; g) envoyer de l’information de {org} vers une messagerie ou un stockage personnels.",
              mod="must not", refs=["ISO 27002:2022 5.10", "ISO 27002:2022 8.19"]),
            C("X02", "Users must not speak publicly or on social media on behalf of {org} unless authorized to do so.",
              "Les utilisateurs ne doivent pas s’exprimer publiquement ou dans les médias sociaux au nom de {org} sans y être autorisés.", mod="must not"),
            C("X03", "Generative artificial intelligence tools may be used only as allowed by the artificial intelligence use policy.",
              "Les outils d’intelligence artificielle générative ne peuvent être utilisés que dans la mesure permise par la politique d’utilisation de l’intelligence artificielle.",
              mod="may", when=has("DATA-06", "ai_tools", "ai_products")),
        ]),
        S("SEC-REQ-EMAIL", "Email, messaging and internet", "Courriel, messagerie et Internet", [
            C("E01", "Users must treat unexpected requests for credentials, payments or changes to banking details as suspicious and verify them through a separate, known channel before acting.",
              "Les utilisateurs doivent considérer comme suspectes les demandes inattendues d’authentifiants, de paiements ou de modification de coordonnées bancaires et les vérifier par un canal distinct et connu avant d’agir.", refs=["ISO 27002:2022 6.3"]),
            C("E02", "Users must report suspected phishing messages using the reporting method provided by {sec}.",
              "Les utilisateurs doivent signaler les messages d’hameçonnage soupçonnés selon la méthode fournie par {sec}.", refs=["ISO 27002:2022 6.8"]),
        ]),
        S("SEC-REQ-DEVICES", "Devices and departure", "Appareils et départ", [
            C("D01", "Users must protect {org} devices against loss and theft, and report a lost or stolen device immediately.",
              "Les utilisateurs doivent protéger les appareils de {org} contre la perte et le vol et signaler immédiatement un appareil perdu ou volé.", refs=["ISO 27002:2022 8.1"]),
            C("D02", "Personal devices must not be used to access {org} email or data.",
              "Les appareils personnels ne doivent pas être utilisés pour accéder au courriel ou aux données de {org}.",
              mod="must not", src="answer", inputs=["TECH-02B"], when=lambda p: p.value("TECH-02B") == "no"),
            C("D03", "Personal devices may access {org} information only under the conditions of the remote work and mobile device policy.",
              "Les appareils personnels ne peuvent accéder à l’information de {org} qu’aux conditions de la politique de télétravail et d’appareils mobiles.",
              mod="may", src="answer", inputs=["TECH-02B"], when=lambda p: p.value("TECH-02B") in ("limited", "yes")),
            C("D04", "When leaving {org} or changing role, users must return all assets and information and must not keep copies of {org} information.",
              "Au départ de {org} ou lors d’un changement de fonctions, les utilisateurs doivent restituer tous les actifs et l’information et ne doivent pas en conserver de copie.", refs=["ISO 27002:2022 5.11"]),
        ]),
        S("SEC-REQ-MONITOR", "Monitoring and privacy", "Surveillance et vie privée", [
            C("M01", by="DEC-AUP-MONITOR", src="decision", legal=True, variants={
                "yes_notice": V("{org} logs and may monitor the use of its systems for security purposes, within the limits of the law. Access to the content of a user’s communications is limited to authorized investigations approved by [ROLE: authority that approves individual investigations].",
                                "{org} journalise et peut surveiller l’utilisation de ses systèmes à des fins de sécurité, dans les limites de la loi. L’accès au contenu des communications d’un utilisateur est limité aux enquêtes autorisées approuvées par [RÔLE : autorité qui approuve les enquêtes individuelles]."),
                "no": V("{org} does not systematically monitor the use of its systems; logs are used to detect and investigate security incidents.",
                        "{org} ne surveille pas systématiquement l’utilisation de ses systèmes; les journaux servent à détecter les incidents de sécurité et à enquêter."),
                "_none": V("[DECISION: State whether and how system use is monitored (legal review required).]", "[DÉCISION : Préciser si et comment l’utilisation des systèmes est surveillée (révision juridique requise).]")}),
        ]),
        S("SEC-REQ-ACK", "Acknowledgement", "Attestation", [
            C("K01", "Users must acknowledge this policy before receiving access and each time it changes materially.",
              "Les utilisateurs doivent attester avoir pris connaissance de la présente politique avant d’obtenir un accès et chaque fois qu’elle change de façon importante.", refs=["ISO 27002:2022 6.2"]),
        ]),
    ],
)

# ------------------------------------------------------------------ IAM
IAM = topic_frame(
    purpose=[C("P01", "This policy ensures that only identified, authenticated and authorized people, devices and services access {org}’s information and systems, with the least privilege necessary. Access is a business decision implemented through technology.",
               "La présente politique garantit que seuls des personnes, appareils et services identifiés, authentifiés et autorisés accèdent à l’information et aux systèmes de {org}, avec le moindre privilège nécessaire. L’accès est une décision d’affaires mise en œuvre par la technologie.", mod="info")],
    scope_extra=[C("SC03", "It covers user, privileged, service, shared-function and third-party accounts on all systems, including cloud and software-as-a-service applications.",
                   "Elle vise les comptes d’utilisateurs, privilégiés, de service, fonctionnels et de tiers sur tous les systèmes, y compris les applications infonuagiques et SaaS.", mod="info")],
    roles=[
        C("R01", "Information and system owners define who may have access, approve access requests and recertify access.", "Les responsables de l’information et des systèmes déterminent qui peut avoir accès, approuvent les demandes d’accès et recertifient les accès."),
        C("R02", "Managers request access for their staff based on their duties and report role changes and departures without delay.", "Les gestionnaires demandent les accès de leur personnel selon ses fonctions et signalent sans délai les changements de fonctions et les départs."),
        C("R03", "Human resources notifies joiners, movers and leavers to the access administration function.", "Les ressources humaines avisent la fonction d’administration des accès des arrivées, mouvements et départs."),
        C("R04", "The access administration function provisions, modifies and removes access only on approved requests and keeps records.", "La fonction d’administration des accès attribue, modifie et retire les accès uniquement sur demande approuvée et conserve les traces."),
        C("R05", "{sec} sets authentication standards, oversees privileged access and reports on access risks.", "{sec} établit les normes d’authentification, supervise les accès privilégiés et rend compte des risques liés aux accès."),
    ],
    requirements=[
        S("SEC-REQ-IDENTITY", "Identities and accounts", "Identités et comptes", [
            C("I01", "Each person must have a unique identity. Shared accounts are prohibited except where technically unavoidable, approved by the system owner, assigned to a named custodian and logged.",
              "Chaque personne doit avoir une identité unique. Les comptes partagés sont interdits, sauf lorsque techniquement inévitables, approuvés par le responsable du système, confiés à un gardien nommé et journalisés.", refs=["ISO 27002:2022 5.16"]),
            C("I02", "Service and other non-human accounts must have a named owner, a documented purpose, only the permissions required, and credentials that are protected and rotated according to the authentication standard.",
              "Les comptes de service et autres comptes non humains doivent avoir un responsable nommé, une finalité documentée, uniquement les permissions requises et des authentifiants protégés et renouvelés selon la norme d’authentification.", refs=["ISO 27002:2022 5.16", "ISO 27002:2022 5.17"]),
            C("I03", "The organization’s central identity provider ({idp}) must be used for authentication wherever applications support it.",
              "Le fournisseur d’identité central de l’organisation ({idp}) doit être utilisé pour l’authentification partout où les applications le permettent.",
              src="answer", inputs=["TECH-04B"], when=lambda p: p.answered("TECH-04B")),
        ]),
        S("SEC-REQ-GRANT", "Granting, changing and removing access", "Attribution, modification et retrait des accès", [
            C("G01", by="DEC-IAM-APPROVER", src="decision", variants={
                "owner": V("Access must be granted only on a documented request approved by the owner of the system or information, based on business need and least privilege.",
                           "L’accès doit être accordé uniquement sur demande documentée approuvée par le responsable du système ou de l’information, selon le besoin d’affaires et le moindre privilège."),
                "manager_owner": V("Access must be granted only on a documented request approved by the person’s manager and by the owner of the system or information, based on business need and least privilege.",
                                   "L’accès doit être accordé uniquement sur demande documentée approuvée par le gestionnaire de la personne et par le responsable du système ou de l’information, selon le besoin d’affaires et le moindre privilège."),
                "_none": V("Access must be granted only on a documented request approved by [DECISION: role(s) that approve access requests], based on business need and least privilege.",
                           "L’accès doit être accordé uniquement sur demande documentée approuvée par [DÉCISION : rôle(s) qui approuvent les demandes d’accès], selon le besoin d’affaires et le moindre privilège.")},
              refs=["ISO 27002:2022 5.15", "ISO 27002:2022 5.18", "NIST CSF 2.0 PR.AA"]),
            C("G02", "Access should be assigned through roles or groups defined by owners rather than to individuals directly.",
              "L’accès devrait être attribué au moyen de rôles ou de groupes définis par les responsables plutôt que directement aux personnes.", mod="should"),
            C("G03", "When a person changes role, access no longer required must be removed, and any new access must be requested and approved as for a new access request.",
              "Lorsqu’une personne change de fonctions, les accès qui ne sont plus requis doivent être retirés, et tout nouvel accès doit être demandé et approuvé comme une nouvelle demande d’accès.", refs=["ISO 27002:2022 5.18"]),
            C("G04", by="DEC-IAM-LEAVER", src="decision", variants={
                "same_day": V("All access of a departing person must be disabled no later than the end of their last working day, and immediately in the case of an involuntary departure.",
                              "Tous les accès d’une personne qui quitte doivent être désactivés au plus tard à la fin de son dernier jour de travail, et immédiatement en cas de départ non volontaire."),
                "24h": V("All access of a departing person must be disabled within 24 hours of departure, and immediately in the case of an involuntary departure.",
                         "Tous les accès d’une personne qui quitte doivent être désactivés dans les 24 heures suivant son départ, et immédiatement en cas de départ non volontaire."),
                "72h": V("All access of a departing person must be disabled within 72 hours of departure, and immediately in the case of an involuntary departure.",
                         "Tous les accès d’une personne qui quitte doivent être désactivés dans les 72 heures suivant son départ, et immédiatement en cas de départ non volontaire."),
                "_none": V("All access of a departing person must be disabled within [DECISION: deadline to disable access after departure].",
                           "Tous les accès d’une personne qui quitte doivent être désactivés dans un délai de [DÉCISION : délai de désactivation des accès après un départ].")},
              refs=["ISO 27002:2022 5.18", "ISO 27002:2022 6.5"]),
            C("G05", "Accounts unused for [VALUE: number of days of inactivity] must be disabled unless an exception is approved.",
              "Les comptes inutilisés depuis [VALEUR : nombre de jours d’inactivité] doivent être désactivés, sauf dérogation approuvée."),
        ]),
        S("SEC-REQ-AUTH", "Authentication", "Authentification", [
            C("A01", by="DEC-IAM-MFA-SCOPE", src="decision", variants={
                "all": V("Multi-factor authentication must be used by all users on every system that supports it.",
                         "L’authentification multifacteur doit être utilisée par tous les utilisateurs sur tous les systèmes qui la permettent."),
                "remote_priv_cloud": V("Multi-factor authentication must be used for all remote access, all privileged accounts, email and all internet-accessible cloud services.",
                                       "L’authentification multifacteur doit être utilisée pour tout accès à distance, tous les comptes privilégiés, le courriel et tous les services infonuagiques accessibles par Internet."),
                "priv": V("Multi-factor authentication must be used for all privileged accounts.",
                          "L’authentification multifacteur doit être utilisée pour tous les comptes privilégiés."),
                "_none": V("Multi-factor authentication must be used for [DECISION: scope of mandatory multi-factor authentication].",
                           "L’authentification multifacteur doit être utilisée pour [DÉCISION : portée de l’authentification multifacteur obligatoire].")},
              refs=["ISO 27002:2022 8.5", "NIST CSF 2.0 PR.AA"],
              gap=("TECH-04", ["no", "partial"], V("MFA is not yet deployed to the required scope.", "L’AMF n’est pas encore déployée selon la portée requise."))),
            C("A02", "Passwords must meet the authentication standard approved by {sec}, which favours length, blocks known-compromised passwords and does not require periodic changes unless compromise is suspected.",
              "Les mots de passe doivent respecter la norme d’authentification approuvée par {sec}, qui privilégie la longueur, bloque les mots de passe connus comme compromis et n’exige pas de changement périodique sauf soupçon de compromission.",
              refs=["ISO 27002:2022 5.17"]),
            C("A03", "Default passwords must be changed before a system or device is put into service.",
              "Les mots de passe par défaut doivent être changés avant la mise en service d’un système ou d’un appareil.", refs=["ISO 27002:2022 8.9"]),
        ]),
        S("SEC-REQ-PRIV", "Privileged access", "Accès privilégiés", [
            C("PA01", "Administrators must use a separate privileged account for administrative tasks and their regular account for email, browsing and other daily work.",
              "Les administrateurs doivent utiliser un compte privilégié distinct pour les tâches d’administration et leur compte ordinaire pour le courriel, la navigation et le travail courant.", refs=["ISO 27002:2022 8.2"]),
            C("PA02", "Privileged access must be limited in number, approved by {sec} in addition to the system owner, logged, and granted for the shortest time practical.",
              "Les accès privilégiés doivent être limités en nombre, approuvés par {sec} en plus du responsable du système, journalisés et accordés pour la durée la plus courte possible.", refs=["ISO 27002:2022 8.2", "NIST CSF 2.0 PR.AA"]),
            C("PA03", "Emergency (“break-glass”) accounts must be protected, used only under documented conditions, and every use must be reviewed after the fact.",
              "Les comptes d’urgence doivent être protégés, utilisés uniquement dans des conditions documentées, et chaque utilisation doit être revue a posteriori.", refs=["ISO 27002:2022 8.2"]),
            C("PA04", "No single person should be able to both request and approve their own privileged access, or to perform and conceal a critical transaction.",
              "Aucune personne ne devrait pouvoir à la fois demander et approuver son propre accès privilégié, ni effectuer et dissimuler une opération critique.", mod="should", refs=["ISO 27002:2022 5.3"]),
        ]),
        S("SEC-REQ-REVIEW", "Access reviews", "Revues des accès", [
            C("RV10", by="DEC-IAM-REVIEW", src="decision", variants={
                "quarterly_priv": V("Owners must review and recertify privileged access every three months and all other access at least annually; access that is no longer justified must be removed.",
                                    "Les responsables doivent revoir et recertifier les accès privilégiés tous les trois mois et tous les autres accès au moins une fois par année; les accès qui ne sont plus justifiés doivent être retirés."),
                "semiannual": V("Owners must review and recertify all access every six months; access that is no longer justified must be removed.",
                                "Les responsables doivent revoir et recertifier tous les accès tous les six mois; les accès qui ne sont plus justifiés doivent être retirés."),
                "annual": V("Owners must review and recertify all access at least annually; access that is no longer justified must be removed.",
                            "Les responsables doivent revoir et recertifier tous les accès au moins une fois par année; les accès qui ne sont plus justifiés doivent être retirés."),
                "_none": V("Owners must review and recertify access [DECISION: access review frequency]; access that is no longer justified must be removed.",
                           "Les responsables doivent revoir et recertifier les accès [DÉCISION : fréquence des revues d’accès]; les accès qui ne sont plus justifiés doivent être retirés.")},
              refs=["ISO 27002:2022 5.18", "NIST CSF 2.0 PR.AA"]),
        ]),
        S("SEC-REQ-THIRD", "Third-party access", "Accès des tiers", [
            C("T01", "Supplier and contractor access must be sponsored by a named {org} manager, limited to the contract’s purpose and duration, and removed when the engagement ends.",
              "L’accès des fournisseurs et contractuels doit être parrainé par un gestionnaire nommé de {org}, limité à l’objet et à la durée du contrat et retiré à la fin de l’engagement.", refs=["ISO 27002:2022 5.19"]),
        ]),
    ],
)

# ------------------------------------------------------------------ Classification and handling
CLASS = topic_frame(
    purpose=[C("P01", "This policy establishes the single information classification scheme of {org} and the minimum handling rules for each level, so that information is protected according to its sensitivity and value.",
               "La présente politique établit le schéma unique de classification de l’information de {org} et les règles minimales de manipulation pour chaque niveau, afin que l’information soit protégée selon sa sensibilité et sa valeur.", mod="info")],
    scope_extra=[],
    roles=[
        C("R01", "Information owners classify their information, review the classification when its context changes, and approve sharing outside the authorized audience.", "Les responsables de l’information classifient leur information, revoient la classification lorsque le contexte change et approuvent le partage hors du public autorisé."),
        C("R02", "Custodians apply the safeguards required for each level.", "Les gardiens appliquent les mesures exigées pour chaque niveau."),
        C("R03", "Users handle information according to its classification.", "Les utilisateurs manipulent l’information selon sa classification."),
        C("R04", "{sec} maintains the handling standard and advises owners.", "{sec} tient à jour la norme de manipulation et conseille les responsables."),
    ],
    requirements=[
        S("SEC-REQ-SCHEME", "Classification scheme", "Schéma de classification", [
            C("K01", "{org} uses the following classification levels, from least to most sensitive: {class_levels}. No other scheme may be used.",
              "{org} utilise les niveaux de classification suivants, du moins au plus sensible : {class_levels}. Aucun autre schéma ne peut être utilisé.",
              inputs=["DATA-02B"], refs=["ISO 27002:2022 5.12"]),
            {"id": "K02", "dynamic": "class_table", "modality": "info", "src": "framework", "refs": ["ISO 27002:2022 5.12"], "inputs": ["DATA-02B"]},
            C("K03", by="DEC-CLASS-DEFAULT", src="decision", variants={
                "internal": V("Information that has not been classified must be handled as Internal until its owner classifies it.",
                              "L’information qui n’a pas été classifiée doit être traitée comme Interne jusqu’à ce que son responsable la classifie."),
                "confidential": V("Information that has not been classified must be handled as Confidential until its owner classifies it.",
                                  "L’information qui n’a pas été classifiée doit être traitée comme Confidentielle jusqu’à ce que son responsable la classifie."),
                "_none": V("Information that has not been classified must be handled as [DECISION: default classification level] until its owner classifies it.",
                           "L’information qui n’a pas été classifiée doit être traitée comme [DÉCISION : niveau de classification par défaut] jusqu’à ce que son responsable la classifie.")}),
            C("K04", "Personal information is classified at least Confidential.", "Les renseignements personnels sont classifiés au moins Confidentiel.",
              src="answer", inputs=["DATA-01"], when=lambda p: p.handles_pi and not p.answered("DATA-02B")),
            C("K05", "Owners consider confidentiality, integrity and availability, and the higher sensitivity that results from combining information.",
              "Les responsables tiennent compte de la confidentialité, de l’intégrité et de la disponibilité, ainsi que de la sensibilité accrue qui découle de la combinaison d’informations.", mod="should"),
        ]),
        S("SEC-REQ-HANDLING", "Handling rules", "Règles de manipulation", [
            C("H01", "Information classified Confidential or above must be shared only with persons authorized by the owner and must be encrypted when stored on portable devices or removable media and when transmitted over public networks.",
              "L’information classifiée Confidentiel ou plus doit être communiquée uniquement aux personnes autorisées par le responsable et doit être chiffrée lorsqu’elle est stockée sur un appareil portable ou un support amovible et lorsqu’elle est transmise sur un réseau public.",
              refs=["ISO 27002:2022 5.14", "ISO 27002:2022 8.24"]),
            C("H02", "Information classified {class_top} must be stored only in systems approved by {sec} for that level, access must be logged, and any external transfer must be approved in advance by the owner.",
              "L’information classifiée {class_top} doit être stockée uniquement dans des systèmes approuvés par {sec} pour ce niveau, l’accès doit être journalisé et tout transfert externe doit être approuvé au préalable par le responsable.",
              refs=["ISO 27002:2022 5.14", "ISO 27002:2022 8.3"]),
            C("H03", "Documents and messages classified Confidential or above should carry a visible label.",
              "Les documents et messages classifiés Confidentiel ou plus devraient porter une mention visible.", mod="should", refs=["ISO 27002:2022 5.13"]),
            C("H04", "Information and media must be disposed of by secure methods appropriate to their classification; paper classified Confidential or above must be shredded and storage media sanitized or destroyed.",
              "L’information et les supports doivent être éliminés par des méthodes sécuritaires adaptées à leur classification; le papier classifié Confidentiel ou plus doit être déchiqueté et les supports de stockage assainis ou détruits.",
              refs=["ISO 27002:2022 7.14", "ISO 27002:2022 8.10"]),
            C("H05", "Information must be kept only as long as required by the retention schedule, then destroyed or anonymized.",
              "L’information doit être conservée seulement le temps prévu au calendrier de conservation, puis détruite ou anonymisée.",
              src="answer", inputs=["DATA-04"], when=lambda p: p.value("DATA-04") in ("yes", "partial"), refs=["ISO 27002:2022 5.33"]),
            C("H06", "[DECISION: Establish a records retention schedule.] Until it is approved, information must not be destroyed when it may be needed for legal, contractual or investigative purposes.",
              "[DÉCISION : Établir un calendrier de conservation.] D’ici son approbation, l’information ne doit pas être détruite si elle peut être requise à des fins légales, contractuelles ou d’enquête.",
              when=lambda p: p.value("DATA-04") not in ("yes", "partial"), legal=True),
        ]),
    ],
)

# ------------------------------------------------------------------ Incident management
IR = topic_frame(
    purpose=[C("P01", "This policy ensures that security incidents affecting {org} are reported, assessed, contained and resolved quickly, that the right people decide, and that lessons are learned.",
               "La présente politique assure que les incidents de sécurité touchant {org} sont signalés, évalués, maîtrisés et résolus rapidement, que les bonnes personnes décident et que des leçons en sont tirées.", mod="info")],
    scope_extra=[C("SC03", "It covers all security events and incidents, including those that occur at suppliers and those involving personal information.",
                   "Elle vise tous les événements et incidents de sécurité, y compris ceux qui surviennent chez des fournisseurs et ceux qui touchent des renseignements personnels.", mod="info")],
    roles=[
        C("R01", "Every user reports suspected incidents according to this policy.", "Chaque utilisateur signale les incidents soupçonnés conformément à la présente politique."),
        C("R02", "{sec} coordinates the incident response, leads the technical response, keeps the incident register and decision log, and reports to management.",
          "{sec} coordonne l’intervention, dirige l’intervention technique, tient le registre des incidents et le journal des décisions et rend compte à la direction."),
        C("R03", "An executive designated by [APPROVER: chief executive] leads the organizational response to major incidents, including communications and business decisions.",
          "Un dirigeant désigné par [APPROBATEUR : premier dirigeant] dirige la réponse de l’organisation aux incidents majeurs, y compris les communications et les décisions d’affaires."),
        C("R04", "{Privacy} assesses incidents involving personal information and the obligations that may follow.", "{Privacy} évalue les incidents touchant des renseignements personnels et les obligations qui peuvent en découler.",
          when=lambda p: p.handles_pi),
        C("R05", "Legal counsel advises on notification, evidence and communications to third parties.", "Le conseiller juridique conseille sur la notification, la preuve et les communications aux tiers.",
          when=lambda p: p.has("ORG-13", "legal") or p.value("REG-10") == "yes"),
    ],
    requirements=[
        S("SEC-REQ-REPORT", "Reporting", "Signalement", [
            C("RP01", by="DEC-IR-REPORT", src="decision", variants={
                "immediately": V("Any person who observes or suspects a security incident, including a lost device, a phishing message that was acted upon or an unusual system behaviour, must report it immediately to {sec} through the published reporting channel.",
                                 "Toute personne qui constate ou soupçonne un incident de sécurité, y compris la perte d’un appareil, un message d’hameçonnage auquel elle a donné suite ou un comportement inhabituel d’un système, doit le signaler immédiatement à {sec} par le canal de signalement publié."),
                "1h": V("Any person who observes or suspects a security incident must report it to {sec} through the published reporting channel within one hour of noticing it.",
                        "Toute personne qui constate ou soupçonne un incident de sécurité doit le signaler à {sec} par le canal de signalement publié dans l’heure suivant sa constatation."),
                "same_day": V("Any person who observes or suspects a security incident must report it to {sec} through the published reporting channel the same working day.",
                              "Toute personne qui constate ou soupçonne un incident de sécurité doit le signaler à {sec} par le canal de signalement publié le jour ouvrable même."),
                "_none": V("Any person who observes or suspects a security incident must report it to {sec} within [DECISION: internal reporting deadline].",
                           "Toute personne qui constate ou soupçonne un incident de sécurité doit le signaler à {sec} dans un délai de [DÉCISION : délai de signalement interne].")},
              refs=["ISO 27002:2022 6.8", "NIST CSF 2.0 RS.MA"]),
            C("RP02", "Reporting a mistake in good faith will not, in itself, lead to disciplinary action.", "Le signalement de bonne foi d’une erreur n’entraîne pas, en soi, de mesure disciplinaire.", mod="info"),
            C("RP03", "Suppliers must report incidents affecting {org} information or services according to their contracts and the third-party security policy.",
              "Les fournisseurs doivent signaler les incidents touchant l’information ou les services de {org} conformément à leurs contrats et à la politique de sécurité des tiers.", refs=["ISO 27002:2022 5.20"]),
        ]),
        S("SEC-REQ-RESPONSE", "Assessment and response", "Évaluation et intervention", [
            C("RS01", "{sec} must assess each reported event, decide whether it is an incident and assign a severity level according to the severity scale in the incident response plan: [TECHNICAL_DETAIL: severity scale and criteria].",
              "{sec} doit évaluer chaque événement signalé, déterminer s’il s’agit d’un incident et lui attribuer un niveau de gravité selon l’échelle du plan de réponse aux incidents : [DÉTAIL_TECHNIQUE : échelle et critères de gravité].",
              refs=["ISO 27002:2022 5.25", "NIST CSF 2.0 RS.AN"]),
            C("RS02", by="DEC-IR-AUTHORITY", src="decision", variants={
                "security_lead": V("{sec} is authorized to isolate systems, disable accounts or suspend services when needed to contain an incident.",
                                   "{sec} est autorisé à isoler des systèmes, désactiver des comptes ou suspendre des services lorsque c’est nécessaire pour maîtriser un incident."),
                "security_lead_exec": V("{sec} is authorized to isolate systems, disable accounts or suspend services when needed to contain an incident, and must inform the designated executive without delay.",
                                        "{sec} est autorisé à isoler des systèmes, désactiver des comptes ou suspendre des services lorsque c’est nécessaire pour maîtriser un incident, et doit en informer sans délai le dirigeant désigné."),
                "exec": V("Only the designated executive may authorize isolating systems or suspending services; {sec} may disable compromised accounts immediately.",
                          "Seul le dirigeant désigné peut autoriser l’isolement de systèmes ou la suspension de services; {sec} peut désactiver immédiatement des comptes compromis."),
                "_none": V("[DECISION: Name who may isolate systems or suspend services during an incident.]", "[DÉCISION : Désigner qui peut isoler des systèmes ou suspendre des services pendant un incident.]")},
              refs=["ISO 27002:2022 5.26", "NIST CSF 2.0 RS.MI"]),
            C("RS03", "Response follows the incident response plan: contain, eradicate, recover and verify, while preserving evidence.",
              "L’intervention suit le plan de réponse aux incidents : maîtriser, éradiquer, rétablir et vérifier, tout en préservant la preuve.",
              refs=["ISO 27002:2022 5.26", "ISO 27002:2022 5.28"], gap=("TECH-08", lambda p: p.answered("TECH-08") and not p.has("TECH-08", "ir_plan"), V("No written incident response plan was reported.", "Aucun plan écrit de réponse aux incidents n’a été indiqué."))),
            C("RS04", "Decisions taken during a major incident, with their time and author, must be recorded in a decision log.",
              "Les décisions prises pendant un incident majeur, avec leur heure et leur auteur, doivent être consignées dans un journal des décisions."),
            C("RS05", "Any decision to pay a ransom or otherwise deal with an extortion demand is reserved to [APPROVER: authority for extortion decisions], after legal advice.",
              "Toute décision de payer une rançon ou de donner suite autrement à une demande d’extorsion est réservée à [APPROBATEUR : autorité pour les décisions d’extorsion], après avis juridique.", legal=True),
        ]),
        S("SEC-REQ-NOTIFY", "Notification and communication", "Notification et communication", [
            C("NT01", "{sec}, with legal counsel and {privacy} where personal information is involved, must assess without delay whether an incident must be notified to regulators, affected individuals, clients, insurers or law enforcement. Only authorized persons may communicate externally about an incident.",
              "{sec}, avec le conseiller juridique et {privacy} lorsque des renseignements personnels sont en cause, doit évaluer sans délai si un incident doit être notifié aux régulateurs, aux personnes concernées, aux clients, aux assureurs ou aux forces de l’ordre. Seules les personnes autorisées peuvent communiquer à l’externe au sujet d’un incident.",
              legal=True, refs=["ISO 27002:2022 5.26", "NIST CSF 2.0 RS.CO"]),
            C("NT02", "Every confidentiality incident involving personal information must be recorded in the register of confidentiality incidents.",
              "Tout incident de confidentialité touchant des renseignements personnels doit être consigné au registre des incidents de confidentialité.",
              src="obligation", obligation="QC-P39.1", legal=True),
            C("NT03", "Notification deadlines and thresholds under the laws confirmed as applicable are documented in the incident response plan: [SOURCE: notification requirements confirmed by legal review].",
              "Les délais et seuils de notification prévus par les lois dont l’applicabilité est confirmée sont documentés dans le plan de réponse aux incidents : [SOURCE : exigences de notification confirmées par la révision juridique].",
              legal=True),
        ]),
        S("SEC-REQ-LEARN", "Learning and readiness", "Leçons et préparation", [
            C("LN01", "A post-incident review must be held for every major incident to identify causes and improvements; agreed actions are tracked to completion.",
              "Une revue post-incident doit être tenue pour chaque incident majeur afin d’en déterminer les causes et les améliorations; les actions convenues sont suivies jusqu’à leur réalisation.",
              refs=["ISO 27002:2022 5.27", "NIST CSF 2.0 ID.IM"]),
            C("LN02", by="DEC-IR-EXERCISE", src="decision", variants={
                "annual": V("The incident response plan must be exercised at least annually, including the executive decision-making part.",
                            "Le plan de réponse aux incidents doit être mis à l’essai au moins une fois par année, y compris le volet décisionnel de la direction."),
                "semiannual": V("The incident response plan must be exercised twice a year, including the executive decision-making part at least once.",
                                "Le plan de réponse aux incidents doit être mis à l’essai deux fois par année, y compris le volet décisionnel de la direction au moins une fois."),
                "_none": V("The incident response plan must be exercised [DECISION: exercise frequency].", "Le plan de réponse aux incidents doit être mis à l’essai [DÉCISION : fréquence des exercices].")},
              refs=["ISO 27002:2022 5.24"]),
        ]),
    ],
)
